/* ===== plugins/CharacterCounter.js ===== */
try { (function (YM) {
// CharacterCounter (port): shows how many characters you typed, coloured as you approach the limit.
(function () {
  const DEFAULT_MAX = 2000;
  YM.definePlugin({
    name: 'CharacterCounter',
    description: 'Shows a character counter in the message box that turns yellow and red near the limit.',
    authors: ['Vencord (ported to Yapper)'],
    tags: ['Chat', 'Utility'],
    options: {
      alwaysShow: { type: 'boolean', default: false, description: 'Always show the counter (otherwise only from 50% of the limit)' },
    },
    start(ctx) {
      const h = YM.dom.h;
      const counter = h('span', { class: 'ym-cc', 'aria-live': 'off', hidden: true });
      let current = null;

      function update() {
        const ta = document.querySelector('.composer textarea');
        if (!ta) {
          counter.hidden = true;
          return;
        }
        const host = ta.closest('.composer');
        if (host && counter.parentNode !== host) host.append(counter);
        current = ta;
        const max = ta.maxLength > 0 ? ta.maxLength : DEFAULT_MAX;
        const len = Array.from(ta.value).length;
        const show = len > 0 && (ctx.settings.store.alwaysShow || len >= max * 0.5);
        counter.hidden = !show;
        counter.textContent = len + ' / ' + max;
        counter.dataset.level = len > max ? 'over' : len >= max * 0.9 ? 'high' : len >= max * 0.75 ? 'warn' : 'ok';
      }

      const onInput = (e) => {
        if (e.target instanceof Element && e.target.matches('.composer textarea')) update();
      };
      document.addEventListener('input', onInput, true);
      ctx.cleanup(() => document.removeEventListener('input', onInput, true));
      ctx.watch('.composer textarea', update);
      ctx.interval(update, 300); // the box is cleared programmatically after sending, which fires no event
      ctx.cleanup(ctx.settings.onChange(update));
      ctx.cleanup(() => {
        counter.remove();
        current = null;
      });
      ctx.css(`
.composer{position:relative}
.ym-cc{position:absolute;right:14px;bottom:-16px;font-size:11px;font-weight:600;color:var(--text-muted);pointer-events:none;font-variant-numeric:tabular-nums}
.ym-cc[data-level=warn]{color:var(--warning)}.ym-cc[data-level=high]{color:#ff9f43}.ym-cc[data-level=over]{color:var(--danger)}
`);
    },
  });
})();

})(YM); } catch (e) { console.error("[YapCord] failed to load plugins/CharacterCounter.js", e); }

/* ===== plugins/ClearURLs.js ===== */
try { (function (YM) {
// ClearURLs (port, built-in rule subset): removes tracking parameters from links in messages you send.
(function () {
  const COMMON = [
    /^utm_/i, /^fbclid$/i, /^gclid$/i, /^gclsrc$/i, /^dclid$/i, /^gbraid$/i, /^wbraid$/i, /^msclkid$/i, /^mc_cid$/i, /^mc_eid$/i,
    /^igshid$/i, /^igsh$/i, /^ref_src$/i, /^ref_url$/i, /^twclid$/i, /^yclid$/i, /^_ga$/i, /^_gl$/i, /^vero_id$/i, /^vero_conv$/i,
    /^oly_enc_id$/i, /^oly_anon_id$/i, /^__s$/i, /^mkt_tok$/i, /^trk$/i, /^trkcampaign$/i, /^hsa_/i, /^s_cid$/i, /^pk_(campaign|kwd|source|medium)$/i,
    /^wickedid$/i, /^_hsenc$/i, /^_hsmi$/i, /^__hstc$/i, /^__hssc$/i, /^__hsfp$/i, /^ttclid$/i, /^li_fat_id$/i, /^epik$/i, /^ocid$/i,
  ];
  // Parameters that are only tracking on specific sites.
  const SITE = [
    { host: /(^|\.)(youtube\.com|youtu\.be|music\.youtube\.com)$/i, params: [/^si$/i, /^pp$/i, /^feature$/i] },
    { host: /(^|\.)(spotify\.com|spotify\.link)$/i, params: [/^si$/i, /^context$/i, /^nd$/i, /^dlsi$/i] },
    { host: /(^|\.)(twitter\.com|x\.com)$/i, params: [/^s$/i, /^t$/i, /^ref_src$/i] },
    { host: /(^|\.)(amazon\.[a-z.]+)$/i, params: [/^tag$/i, /^ref_?$/i, /^pf_rd_/i, /^pd_rd_/i, /^psc$/i, /^linkcode$/i, /^creative/i, /^th$/i] },
    { host: /(^|\.)(reddit\.com)$/i, params: [/^share_id$/i, /^utm_/i, /^ref$/i, /^ref_source$/i] },
    { host: /(^|\.)(instagram\.com|facebook\.com|tiktok\.com)$/i, params: [/^igshid$/i, /^_t$/i, /^_r$/i, /^is_from_webapp$/i, /^sender_device$/i, /^web_id$/i, /^refer$/i, /^fbclid$/i] },
  ];

  function cleanUrl(raw, extra) {
    let u;
    try {
      u = new URL(raw);
    } catch (_) {
      return raw;
    }
    const sites = SITE.filter((s) => s.host.test(u.hostname));
    let changed = false;
    for (const key of [...u.searchParams.keys()]) {
      if (COMMON.some((re) => re.test(key)) || sites.some((s) => s.params.some((re) => re.test(key))) || extra.has(key.toLowerCase())) {
        u.searchParams.delete(key);
        changed = true;
      }
    }
    if (!changed) return raw;
    return u.toString();
  }

  function clean(content, extraList) {
    const extra = new Set(String(extraList || '').split(/[\s,;]+/).filter(Boolean).map((s) => s.toLowerCase()));
    return content.replace(/https?:\/\/[^\s<>"]+/gi, (match) => {
      const tail = (match.match(/[.,;:!?)\]]+$/) || [''])[0];
      const url = tail ? match.slice(0, -tail.length) : match;
      return cleanUrl(url, extra) + tail;
    });
  }

  YM.definePlugin({
    name: 'ClearURLs',
    description: 'Removes tracking parameters (utm_*, fbclid, ...) from links before your message is sent.',
    authors: ['Vencord (ported to Yapper)'],
    tags: ['Privacy', 'Utility'],
    api: { clean },
    options: {
      extraParams: { type: 'string', default: '', description: 'Extra parameter names to remove (comma separated)' },
    },
    start(ctx) {
      const handler = (msg) => { msg.content = clean(msg.content, ctx.settings.store.extraParams); };
      ctx.cleanup(YM.messageEvents.addPreSendListener(handler));
      ctx.cleanup(YM.messageEvents.addPreEditListener(handler));
    },
  });
})();

})(YM); } catch (e) { console.error("[YapCord] failed to load plugins/ClearURLs.js", e); }

