    retro: { type: 'square', notes: [[392, 0, .1, .2], [523, .1, .1, .2], [659, .2, .1, .2], [784, .3, .1, .2], [1047, .4, .3, .2], [784, .8, .1, .2], [1047, .9, .3, .2]] },
