    const imageTaken = IMAGE_OPTIONS.some((n) => used.has(n)) || before.bare.length > 0;
    const available = OPTIONS.filter((o) => !used.has(o.name) && !(imageTaken && IMAGE_OPTIONS.includes(o.name)));
