    go: 'go', golang: 'go', rust: 'rust', rs: 'rust',
    sh: 'sh', bash: 'sh', zsh: 'sh', shell: 'sh', ps1: 'sh', powershell: 'sh', bat: 'sh', cmd: 'sh',
    sql: 'sql', mysql: 'sql', postgres: 'sql', sqlite: 'sql',
    json: 'json', jsonc: 'json', json5: 'json',
